import "./account-hub-input.mjs"; // eslint-disable-line import/no-unassigned-import

/**
 * Account Hub Email Incoming Form Template
 * Template ID: #accountHubEmailIncomingFormTemplate (from accountHubEmailIncomingFormTemplate.inc.xhtml)
 */
class EmailIncomingForm extends AccountHubStep {
  /**
   * The incoming server protocol.

&.number-input {
  padding-inline-end: 0;

  &::-moz-number-spin-box {
    block-size: 100%;
    padding-block: var(--hub-form-input-block-padding);
    inline-size: 22px;
    border-inline-start: 1px solid var(--color-surface-border);

add_setup(async function () {
  const tab = tabmail.openTab("contentTab", {
    url: "chrome://mochitests/content/browser/comm/mail/components/accountcreation/test/browser/files/accountHubEmailManualIncomingForm.xhtml",
  });

  await BrowserTestUtils.browserLoaded(tab.browser);
  tab.browser.focus();
  browser = tab.browser;
  subview = tab.browser.contentWindow.document.querySelector(
    "email-manual-incoming-form"
  );

add_task(async function test_settingStateLeavesConfigIntact() {
  const config = new AccountConfig();
  config.incoming.type = "imap";
  subview.setState(config);

  const protocolSelector = subview.querySelector("#incomingProtocol");

  Assert.equal(
    protocolSelector.value,
    "1",
    "IMAP should be the selected protocol"
  );
